alter table public.profiles enable row level security;alter table public.admins enable row level security;alter table public.connected_accounts enable row level security;alter table public.projects enable row level security;alter table public.bids enable row level security;alter table public.messages enable row level security;alter table public.assets enable row level security;alter table public.payments enable row level security;alter table public.disputes enable row level security;alter table public.stripe_events enable row level security;alter table public.audit_log enable row level security;alter table public.payment_operations enable row level security;
revoke all on public.profiles,public.admins,public.connected_accounts,public.projects,public.bids,public.messages,public.assets,public.payments,public.disputes,public.stripe_events,public.audit_log,public.payment_operations from anon,authenticated;
grant select on public.profiles,public.projects to anon,authenticated;grant select on public.bids,public.messages,public.assets,public.payments,public.disputes to authenticated;grant insert on public.projects,public.bids,public.messages,public.assets to authenticated;grant update(name,bio,skills) on public.profiles to authenticated;
create policy profiles_read on public.profiles for select using(true);create policy profiles_edit on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy projects_read on public.projects for select using(true);
create policy projects_create on public.projects for insert to authenticated with check(owner_id=auth.uid() and developer_id is null and accepted_bid_id is null and status='open' and deadline>current_date and developer_distribution_consent=false);
create policy bids_read on public.bids for select to authenticated using(developer_id=auth.uid() or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid()) or public.is_admin());
create policy bids_create on public.bids for insert to authenticated with check(developer_id=auth.uid() and exists(select 1 from public.projects p where p.id=project_id and p.owner_id<>auth.uid() and p.status='open'));
create policy messages_read on public.messages for select to authenticated using(public.is_participant(project_id) or public.is_admin());
create policy messages_create on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_participant(project_id) and exists(select 1 from public.projects where id=project_id and status not in('open','completed','refunded')));
create policy assets_read on public.assets for select to authenticated using(public.is_participant(project_id) or public.is_admin());
create policy assets_create on public.assets for insert to authenticated with check(uploader_id=auth.uid() and path like project_id::text||'/'||auth.uid()::text||'/%' and exists(select 1 from public.projects p where p.id=project_id and ((kind='attachment' and p.owner_id=auth.uid() and p.status='open') or (kind='deliverable' and p.developer_id=auth.uid() and p.status='in_progress'))));
create policy payments_read on public.payments for select to authenticated using(public.is_participant(project_id) or public.is_admin());create policy disputes_read on public.disputes for select to authenticated using(public.is_participant(project_id) or public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-files','project-files',false,10485760,array['application/pdf','text/plain','text/markdown','image/png','image/jpeg','image/webp','application/zip','application/x-zip-compressed','application/octet-stream']);
create policy files_read on storage.objects for select to authenticated using(bucket_id='project-files' and exists(select 1 from public.projects p where p.id::text=(storage.foldername(name))[1] and (public.is_participant(p.id) or public.is_admin())));
create policy files_create on storage.objects for insert to authenticated with check(bucket_id='project-files' and (storage.foldername(name))[2]=auth.uid()::text and lower(storage.extension(name)) in('pdf','txt','md','png','jpg','jpeg','webp','zip') and exists(select 1 from public.projects p where p.id::text=(storage.foldername(name))[1] and ((p.owner_id=auth.uid() and p.status='open') or (p.developer_id=auth.uid() and p.status='in_progress'))));
-- No direct updates to status/payment/reputation; no replacement/deletion of uploaded artifacts.
